    }

    public void writeOut(Channel channel, Message serviceMessage, ErrorHandler errorHandler) throws Exception {
        DefaultServiceMessage defaultServiceMessage = (DefaultServiceMessage) ProtoStuffSerializeUtil.unSerializeForCommon(serviceMessage.getBody());

        if (defaultServiceMessage != null) {
            byte[] responseBytes = defaultServiceMessage.getResponseBytes();
            if (responseBytes != null) {
                this.responseContent = responseBytes;
            } else {
                throw new ErrorHandlerException(ErrorType.RESPONSE_NULL, "Response content is null");
            }
        } else {
            throw new ErrorHandlerException(ErrorType.SERVICE_MESSAGE_NULL, "Service message is null");
        }

        ChannelFuture future = channel.writeAndFlush(new DefaultFullHttpResponse(HttpVersion.HTTP_1_1, HttpResponseStatus.OK, responseContent));
        future.addListener(ChannelFutureListener.CLOSE);
    }
}

