import com.groupdocs.metadata.MetadataWriter;

import java.io.FileInputStream;
import java.io.FileOutputStream;
import java.io.IOException;

public class RunExamples {
    public static void main(String[] args) {
        try {
            // Load metadata from PDF file
            MetadataReader reader = MetadataReader.loadFromFile(new FileInputStream("input.pdf"));

            // Create a new metadata builder
            MetadataBuilder builder = new MetadataBuilder();

            // Add new metadata
            builder.add("Author", "John Doe");
            builder.add("Keywords", "example metadata");

            // Save metadata to PDF file
            MetadataWriter writer = MetadataWriter.save(reader, new FileOutputStream("output.pdf"));

            System.out.println("Metadata added successfully.");
        } catch (IOException e) {
            e.printStackTrace();
        }
    }
}

