        this.applicationRepository = applicationRepository;
        this.dataEncryptor = dataEncryptor;
        this.stringEncryptor = stringEncryptor;
    }

    @Test
    public void testSaveApplication() {
        Application application = new Application();
        application.setId(dataEncryptor.encrypt(Integer.toString(12)));
        application.setName(stringEncryptor.encrypt("Test Application"));
        application.setLogText("Test log entry");

        applicationRepository.save(application);

        Application savedApplication = applicationRepository.findById(application.getId());

